CREATE OR REPLACE FUNCTION better_supabase.calendar_feed(token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  v_link uuid;
  v_subject text;
  v_tenant uuid;
  v_calendar uuid;
  v_creator uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if calendar_feed.token is null or length(calendar_feed.token) < 32 then
    return null;
  end if;
  select l."id", l."subject_id", l."tenant_id", l."created_by" into v_link, v_subject, v_tenant, v_creator
  from "better_supabase"."share_links" l
  where l."token_hash" = encode(extensions.digest(convert_to(calendar_feed.token, 'utf8'), 'sha256'), 'hex')
    and l."subject_type" = 'calendar'
    and l."revoked_at" is null
    and (l."expires_at" is null or l."expires_at" > now())
    and (l."max_uses" is null or l."use_count" < l."max_uses")
  for update;
  if v_subject is null or v_subject !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;
  v_calendar := v_subject::uuid;
  if v_creator is null or not coalesce(better_supabase.can_user(v_creator, 'tenant', v_tenant, 'calendar.read'), false) then
    return null;
  end if;
  update "better_supabase"."share_links" set "use_count" = "use_count" + 1, "last_used_at" = now() where "id" = v_link;
  return (
    select jsonb_build_object(
      'calendar', jsonb_build_object('id', k."id", 'name', k."name", 'tz', k."tz"),
      'events', coalesce((
      select jsonb_agg(f.item order by f.starts)
      from (
        select jsonb_build_object('id', e."id", 'calendarId', e."calendar_id", 'uid', e."uid", 'title', e."title", 'startsAt', e."starts_at", 'endsAt', e."ends_at", 'allDay', e."all_day", 'tz', e."tz", 'status', e."status", 'rrule', e."rrule", 'exdates', to_jsonb(e."exdates"), 'recurrenceId', e."recurrence_id", 'originalStart', e."original_start", 'description', e."description", 'location', e."location", 'color', e."color", 'subjectType', e."subject_type", 'subjectId', e."subject_id") || jsonb_build_object('updatedAt', e."updated_at", 'kind', e."kind", 'transparency', e."transparency", 'autoDecline', e."auto_decline", 'attendees', coalesce((select jsonb_agg(jsonb_build_object('email', a."email", 'name', a."name", 'userId', a."user_id", 'role', a."role", 'response', a."response") order by a."email") from "better_supabase"."calendar_attendees" a where a."event_id" = e."id"), '[]'::jsonb), 'alarms', coalesce((select jsonb_agg(jsonb_build_object('id', l."id", 'action', l."action", 'triggerMinutes', l."trigger_minutes", 'related', l."trigger_related", 'triggerAt', l."trigger_at", 'repeat', l."repeat_count", 'repeatMinutes', l."repeat_minutes", 'description', l."description", 'summary', l."summary") order by l."created_at", l."id") from "better_supabase"."calendar_event_alarms" l where l."event_id" = e."id"), '[]'::jsonb)) || jsonb_build_object('reminders', coalesce((select jsonb_agg(jsonb_build_object('method', r."method", 'offsetMinutes', r."offset_minutes") order by r."offset_minutes") from "better_supabase"."reminders" r where r."subject_type" = 'calendar_event' and r."subject_id" = e."id"::text and r."user_id" = v_creator), '[]'::jsonb)) as item, e."starts_at" as starts
        from "better_supabase"."calendar_events" e
        join "better_supabase"."calendars" k on k."id" = e."calendar_id"
        where k."id" = v_calendar
          and (e."rrule" is not null or e."ends_at" > now() - interval '366 days')
          and true
        order by e."starts_at"
        limit 5000
      ) f
    ), '[]'::jsonb)
    )
    from "better_supabase"."calendars" k where k."id" = v_calendar and k."tenant_id" = v_tenant
  );
end;
$function$;

